SELECT IFNULL(SUM(r.work_duration),0) AS actualMinutes
FROM qxx_pro_workrecord r
LEFT JOIN qxx_md_workstation ws ON ws.workstation_id = r.workstation_id AND ws.factory_id = r.factory_id

  r.status = 'CLOSED' AND r.clock_in_time BETWEEN #{begin} AND #{end}

    AND ws.workshop_id IN
    #{id}


    AND r.team_id IN
    #{id}

SELECT ws.workshop_id AS groupId, IFNULL(SUM(r.work_duration),0) AS actualMinutes FROM qxx_pro_workrecord r JOIN qxx_md_workstation ws ON ws.workstation_id = r.workstation_id AND ws.factory_id = r.factory_id
r.status = 'CLOSED' AND r.clock_in_time BETWEEN #{begin} AND #{end}
AND ws.workshop_id IN #{id}
GROUP BY ws.workshop_id

SELECT t.process_id AS groupId, MAX(t.process_name) AS groupName, IFNULL(SUM(r.work_duration),0) AS actualMinutes FROM qxx_pro_workrecord r JOIN qxx_pro_task t ON t.task_id = r.task_id AND t.factory_id = r.factory_id LEFT JOIN qxx_md_workstation ws ON ws.workstation_id = t.workstation_id AND ws.factory_id = t.factory_id
r.status = 'CLOSED' AND r.clock_in_time BETWEEN #{begin} AND #{end}
AND ws.workshop_id IN #{id}
GROUP BY t.process_id

SELECT DATE(t.finish_date) AS statDate, COUNT(*) AS completedCount, SUM(CASE WHEN t.finish_date > t.end_time THEN 1 ELSE 0 END) AS delayedCount, IFNULL(SUM(t.quantity_qualified),0) AS qualifiedQty FROM qxx_pro_task t LEFT JOIN qxx_md_workstation ws ON ws.workstation_id = t.workstation_id AND ws.factory_id = t.factory_id
t.status = 'COMPLETED' AND t.finish_date BETWEEN #{begin} AND #{end} AND ws.workshop_id = #{workshopId}
GROUP BY DATE(t.finish_date)

SELECT DATE(r.clock_in_time) AS statDate, IFNULL(SUM(r.work_duration),0) AS actualMinutes
FROM qxx_pro_workrecord r
LEFT JOIN qxx_md_workstation ws ON ws.workstation_id = r.workstation_id AND ws.factory_id = r.factory_id

  r.status = 'CLOSED' AND r.clock_in_time BETWEEN #{begin} AND #{end}
   AND ws.workshop_id = #{workshopId}

GROUP BY DATE(r.clock_in_time)

SELECT t.status AS status, COUNT(*) AS cnt
FROM qxx_pro_task t
LEFT JOIN qxx_md_workstation ws ON ws.workstation_id = t.workstation_id AND ws.factory_id = t.factory_id

  t.create_time BETWEEN #{begin} AND #{end}
   AND ws.workshop_id = #{workshopId}

GROUP BY t.status
